CREATE TABLE IF NOT EXISTS catalog_origins(catalog_id TEXT PRIMARY KEY REFERENCES catalog_messages(id),content_key TEXT NOT NULL UNIQUE,source TEXT NOT NULL,source_url TEXT NOT NULL,author TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',language TEXT NOT NULL,rights TEXT NOT NULL,source_revision TEXT NOT NULL DEFAULT '',imported_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS catalog_jobs(job TEXT NOT NULL,run_key TEXT NOT NULL,status TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER,added INTEGER NOT NULL DEFAULT 0,detail TEXT NOT NULL DEFAULT '',PRIMARY KEY(job,run_key));
